import type { DndObserver, DndObserverEventCallbacks } from 'dragdoll/dnd-observer';
import { createEffect, onCleanup } from 'solid-js';
import type { MaybeAccessor } from '../utils/maybe-accessor.js';
import { resolveMaybeAccessor } from '../utils/maybe-accessor.js';

export function useDndObserverCallback<
  K extends keyof DndObserverEventCallbacks<any> = keyof DndObserverEventCallbacks,
>(
  eventType: K,
  callback: MaybeAccessor<DndObserverEventCallbacks<any>[K] | undefined>,
  dndObserver: MaybeAccessor<DndObserver<any> | null>,
) {
  createEffect(() => {
    const observer = resolveMaybeAccessor(dndObserver);
    const resolvedCallback = resolveMaybeAccessor(callback);
    if (!observer || !resolvedCallback) return;
    const listenerId = observer.on(eventType, resolvedCallback as any);
    onCleanup(() => observer.off(eventType, listenerId));
  });
}
